import{_ as r,C as i,o as e,c as s,a2 as o,b as l,w as a,a as n,E as c,a3 as h}from"./chunks/framework.BaXgE4DV.js";const B=JSON.parse('{"title":"계정: 로그인, 동의, 삭제","description":"","frontmatter":{},"headers":[],"relativePath":"features/account.md","filePath":"features/account.md","lastUpdated":1791571189000}'),u={name:"features/account.md"};function p(E,t,g,A,C,q){const d=i("Mermaid");return e(),s("div",null,[t[1]||(t[1]=o('<h1 id="계정-로그인-동의-삭제" tabindex="-1">계정: 로그인, 동의, 삭제 <a class="header-anchor" href="#계정-로그인-동의-삭제" aria-label="Permalink to &quot;계정: 로그인, 동의, 삭제&quot;">​</a></h1><p>로그인 수단(Apple 포함), 가입할 때의 약관 동의와 만 14세 이상 확인, 앱 안의 계정 삭제를 다룹니다. 세 가지 모두 스토어 출시에 필요한 <a href="/grato-docs/guide/roadmap#phase-2">2단계</a> 기능입니다. → <a href="/grato-docs/decisions#adr-15">결정 기록 #15</a>, <a href="/grato-docs/operations/compliance#blockers">출시 준비 체크리스트</a></p><h2 id="providers" tabindex="-1">로그인 수단 <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;로그인 수단 {#providers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>수단</th><th>방식</th><th>비고</th></tr></thead><tbody><tr><td>이메일·비밀번호</td><td><code>createUserWithEmailAndPassword</code> / <code>signInWithEmailAndPassword</code></td><td>가입 폼에서 약관에 동의</td></tr><tr><td>Google</td><td><code>signInWithPopup(googleProvider)</code></td><td>로그인 도메인은 커스텀 도메인(<code>VITE_FIREBASE_AUTH_DOMAIN</code>)</td></tr><tr><td><strong>Apple</strong></td><td><code>signInWithPopup(appleProvider)</code>, <code>OAuthProvider(&#39;apple.com&#39;)</code></td><td>범위 <code>email</code>, <code>name</code>, 화면 언어 <code>ko_KR</code></td></tr><tr><td>Google·Apple (iOS·Android 앱)</td><td>네이티브 로그인 화면 → <code>signInWithCredential</code></td><td>웹과 같은 uid. 창을 닫으면 오류 없음 → <a href="/grato-docs/mobile/#sign-in">앱 로그인</a></td></tr></tbody></table><ul><li>로그인 화면에서 &quot;Google로 계속하기&quot;와 &quot;Apple로 계속하기&quot;를 <strong>같은 크기로 나란히</strong> 보여 줍니다(Apple 4.8). 로그인 탭과 가입 탭 모두에 있습니다.</li><li>카카오톡 같은 앱 내 브라우저에서는 두 버튼을 끄고 &quot;앱 내 브라우저에서는 Google·Apple 로그인을 사용할 수 없어요&quot;를 보여 줍니다(OAuth 팝업이 막힘). 이메일 로그인은 됩니다.</li><li>휴대폰·Safari는 팝업 준비 파일을 미리 받아 둬야 버튼을 누른 즉시 팝업이 열립니다. 데스크톱은 버튼에 마우스를 올릴 때 받습니다. → <a href="/grato-docs/architecture/client#performance">성능</a></li></ul><h3 id="apple-로그인의-특징" tabindex="-1">Apple 로그인의 특징 <a class="header-anchor" href="#apple-로그인의-특징" aria-label="Permalink to &quot;Apple 로그인의 특징&quot;">​</a></h3><ul><li><strong>이름</strong>: Apple은 처음 동의할 때만 이름을 주고, Firebase 웹 로그인은 이를 넘겨주지 않습니다. 그래서 Apple 사용자는 이름 &quot;익명&quot;으로 시작하고, 홈에 &quot;이름을 알려주세요&quot; 카드(<code>ProfileNameCard</code>, 닫을 수 있음)가 떠서 MyPage 이름 편집으로 안내합니다.</li><li><strong>이메일 가리기</strong>: 사용자가 &quot;이메일 가리기&quot;를 고르면 <code>…@privaterelay.appleid.com</code> 주소가 옵니다. 그대로 받아들이고, 이 주소로 메일을 보내지는 않습니다.</li><li><strong>같은 이메일, 다른 수단</strong>: Firebase의 &quot;이메일당 계정 하나&quot; 설정에서 이미 다른 수단으로 가입한 이메일이면 <code>auth/account-exists-with-different-credential</code> 오류가 나고, &quot;처음 가입할 때 쓴 방법(Google, Apple 또는 이메일)으로 로그인해주세요&quot;를 보여 줍니다. 계정 연결 기능은 없습니다.</li><li>콘솔 설정(Apple Developer의 Services ID, 키)은 <a href="/grato-docs/operations/deploy#apple-sign-in">배포: Apple 로그인 설정</a>에 있습니다.</li><li>iOS·Android 앱에서는 팝업 대신 휴대폰의 로그인 화면을 쓰고, 받은 토큰으로 웹과 같은 Firebase JS SDK에 로그인합니다. iPhone의 Apple 로그인은 처음 동의할 때 이름을 받아 바로 씁니다. 계정 삭제의 재인증과 Apple 연결 해제(iOS는 인증 코드)도 같은 방식입니다. → <a href="/grato-docs/mobile/#sign-in">앱 로그인</a>, <a href="/grato-docs/decisions#adr-17">결정 기록 #17</a></li></ul><h3 id="로그인할-수-없는-경우" tabindex="-1">로그인할 수 없는 경우 <a class="header-anchor" href="#로그인할-수-없는-경우" aria-label="Permalink to &quot;로그인할 수 없는 경우&quot;">​</a></h3><table tabindex="0"><thead><tr><th>오류</th><th>안내</th></tr></thead><tbody><tr><td><code>auth/user-disabled</code></td><td>&quot;이용이 제한된 계정이에요.&quot; + 고객지원 이메일 (운영자가 <a href="/grato-docs/features/safety#moderate">이용 정지</a>한 계정)</td></tr><tr><td><code>auth/operation-not-allowed</code></td><td>&quot;지금은 이 방법으로 로그인할 수 없어요.&quot; (콘솔에서 해당 수단이 꺼져 있음)</td></tr></tbody></table><h2 id="consent" tabindex="-1">약관 동의와 연령 확인 <a class="header-anchor" href="#consent" aria-label="Permalink to &quot;약관 동의와 연령 확인 {#consent}&quot;">​</a></h2><p>Grato는 <strong>만 14세 이상</strong>만 이용할 수 있습니다(법정대리인 동의 절차 없음). 로그인한 모든 사용자는 현재 약관 버전에 동의한 기록이 있어야 앱을 씁니다.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">users</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{uid}.consent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { termsVersion: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;2026-10&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ageConfirmed: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, at: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">serverTimestamp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() }</span></span></code></pre></div><ul><li>약관 버전은 <code>src/content/legal.js</code>의 <code>TERMS_VERSION</code>입니다. 다시 동의받아야 할 만큼 약관이 바뀌면 이 값을 올립니다. 그러면 모든 사용자가 다음에 열 때 &quot;이용약관이 바뀌었어요&quot; 화면을 봅니다. 처리방침 버전(<code>PRIVACY_VERSION</code>)은 다시 동의받지 않습니다.</li><li>규칙은 정확히 이 형태만 받고(<code>at</code>은 서버 시간), 감사 글·댓글을 만들 때 이 기록이 있는지 확인합니다. 클라이언트 화면을 건너뛰어도 글을 쓸 수 없습니다. → <a href="/grato-docs/architecture/security-rules#consent">보안 규칙</a></li></ul><h3 id="어디서-동의하나요" tabindex="-1">어디서 동의하나요 <a class="header-anchor" href="#어디서-동의하나요" aria-label="Permalink to &quot;어디서 동의하나요&quot;">​</a></h3><table tabindex="0"><thead><tr><th>경로</th><th>동의 시점</th></tr></thead><tbody><tr><td>이메일 가입</td><td>가입 폼의 체크리스트: [필수] 만 14세 이상이에요, [필수] 이용약관에 동의해요(바로 아래 &quot;불쾌하거나 해로운 콘텐츠와 괴롭힘은 무관용 원칙으로 금지, 확인되면 삭제·이용 정지&quot; 안내), 개인정보 처리방침 확인(링크), &quot;모두 동의해요&quot;. 버튼은 &quot;동의하고 가입하기&quot;. Google·Apple로 처음 시작한 사용자는 같은 체크리스트를 동의 화면에서 봅니다. 로그인 화면 아래에도 같은 원칙을 한 줄로 보여 줍니다(App Store 1.2: 가입·로그인 전에 무관용 원칙이 보여야 함)</td></tr><tr><td>Google·Apple, 가입 탭에서 미리 체크</td><td>로그인 직후 바로 기록 (동의 화면 없음)</td></tr><tr><td>Google·Apple, 그 밖의 경우</td><td>로그인 직후 <code>/consent</code> 동의 화면</td></tr><tr><td>기존 사용자 (동의 기록 없음 또는 예전 버전)</td><td>다음에 앱을 열 때 <code>/consent</code></td></tr></tbody></table><h3 id="동의-화면-consent" tabindex="-1">동의 화면 (<code>/consent</code>) <a class="header-anchor" href="#동의-화면-consent" aria-label="Permalink to &quot;동의 화면 (`/consent`)&quot;">​</a></h3><p><code>App.jsx</code>의 <code>ConsentGate</code>가 로그인 페이지들을 감싸, 동의가 필요하면 <code>/consent</code>로 보내고 동의하면 원래 가려던 곳(초대 링크 포함)으로 돌려보냅니다.</p><ul><li><strong>시작을 막지 않습니다</strong>(<a href="/grato-docs/decisions#adr-13">ADR-13</a>). 프로필을 아직 모르면 페이지를 그대로 그리고, 프로필이 오면 판단합니다. 방금 만든 계정(첫 로그인, 생성 10분 이내)은 프로필을 기다리지 않고 바로 묻습니다.</li><li>문구는 세 가지입니다: 새 사용자 &quot;Grato를 시작하기 전에&quot;, 동의 기록이 없는 기존 사용자 &quot;새 이용약관을 확인해주세요&quot;, 버전이 바뀐 사용자 &quot;이용약관이 바뀌었어요&quot;.</li><li>고를 수 있는 것: <strong>동의하고 시작하기</strong>, <strong>만 14세 미만이에요</strong>, <strong>동의하지 않고 로그아웃</strong>, (기존 사용자) <strong>계정 삭제</strong>.</li><li>동의 화면과 계정 삭제 화면은 동의 없이 들어갈 수 있습니다. 새 약관을 거부한 사람도 탈퇴할 수 있어야 하기 때문입니다.</li><li>동의 화면에서는 아래 탭 막대를 숨깁니다.</li></ul><h3 id="만-14세-미만이라고-답하면" tabindex="-1">만 14세 미만이라고 답하면 <a class="header-anchor" href="#만-14세-미만이라고-답하면" aria-label="Permalink to &quot;만 14세 미만이라고 답하면&quot;">​</a></h3><p>만 14세 미만의 정보는 보관하지 않으므로(처리방침 &quot;11. 만 14세 미만 아동&quot;) 계정을 바로 지웁니다.</p><ul><li>방금 만든 계정: &quot;방금 만든 계정은 남기지 않고 로그아웃할게요&quot; → 계정 삭제 후 로그아웃.</li><li>기록이 있는 기존 계정: &quot;계정과 기록을 모두 삭제하고 로그아웃할게요&quot; → <a href="#deletion">계정 삭제</a>와 같은 서버 처리. 다시 로그인이 필요하면 계정 삭제 화면으로 넘어갑니다.</li><li>로그인 화면에 &quot;만 14세 이상부터 이용할 수 있어요&quot;를 한 번 보여 줍니다.</li></ul><h2 id="deletion" tabindex="-1">계정 삭제 <a class="header-anchor" href="#deletion" aria-label="Permalink to &quot;계정 삭제 {#deletion}&quot;">​</a></h2><p>App Store(5.1.1(v)), Google Play, 개인정보 보호법이 요구하는 앱 안의 계정 삭제입니다.</p><table tabindex="0"><thead><tr><th>경로</th><th>설명</th></tr></thead><tbody><tr><td>MyPage › 설정 › <strong>계정 삭제</strong> (<code>/settings/delete-account</code>)</td><td>앱 안에서 바로 삭제</td></tr><tr><td>동의 화면의 &quot;계정 삭제&quot;</td><td>새 약관에 동의하지 않는 기존 사용자</td></tr><tr><td><code>/account-deletion</code> (공개)</td><td>로그인 없이 볼 수 있는 삭제 안내. Google Play에 등록하는 &quot;계정 삭제 URL&quot;이며, 앱을 지운 사람을 위한 이메일 요청 방법도 있음</td></tr></tbody></table><h3 id="삭제-화면" tabindex="-1">삭제 화면 <a class="header-anchor" href="#삭제-화면" aria-label="Permalink to &quot;삭제 화면&quot;">​</a></h3><ul><li>&quot;삭제하면 되돌릴 수 없어요&quot; 경고, <strong>바로 삭제되는 정보</strong>, <strong>Circle은 이렇게 정리돼요</strong>, <strong>누구인지 알 수 없게 남는 정보</strong>를 먼저 보여 줍니다.</li><li>확인 문구 &quot;계정 삭제&quot;를 직접 입력해야 버튼이 켜집니다. 비밀번호 사용자는 비밀번호도 입력합니다.</li><li>Google·Apple 사용자는 본인 확인 팝업이 한 번 더 열립니다. 앱 내 브라우저에서는 팝업이 막히므로 Chrome·Safari에서 열라고 안내합니다.</li><li>앱에서 확인할 수 없는 계정은 고객지원 이메일로 요청하도록 안내합니다.</li></ul><h3 id="흐름" tabindex="-1">흐름 <a class="header-anchor" href="#흐름" aria-label="Permalink to &quot;흐름&quot;">​</a></h3>',27)),(e(),l(h,null,{default:a(()=>[c(d,{id:"mermaid-346",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20U%20as%20%EC%82%AC%EC%9A%A9%EC%9E%90%0A%20%20participant%20C%20as%20%ED%81%B4%EB%9D%BC%EC%9D%B4%EC%96%B8%ED%8A%B8%20(authStore)%0A%20%20participant%20A%20as%20Firebase%20Auth%0A%20%20participant%20F%20as%20deleteAccount%0A%20%20U-%3E%3EC%3A%20%22%EA%B3%84%EC%A0%95%20%EC%82%AD%EC%A0%9C%ED%95%98%EA%B8%B0%22%0A%20%20C-%3E%3EA%3A%20%EC%9E%AC%EC%9D%B8%EC%A6%9D%20(Google%C2%B7Apple%20%ED%8C%9D%EC%97%85%20%EB%98%90%EB%8A%94%20%EB%B9%84%EB%B0%80%EB%B2%88%ED%98%B8)%0A%20%20opt%20Apple%20%EC%82%AC%EC%9A%A9%EC%9E%90%0A%20%20%20%20C-%3E%3EA%3A%20revokeAccessToken%20(Apple%20%EC%97%B0%EA%B2%B0%20%ED%95%B4%EC%A0%9C)%0A%20%20end%0A%20%20C-%3E%3EF%3A%20deleteAccount(%7BappleRevoked%3F%7D)%20%E2%80%94%20%EC%B5%9C%EB%8C%80%20540%EC%B4%88%20%EB%8C%80%EA%B8%B0%0A%20%20F-%3E%3EF%3A%20%ED%86%A0%ED%81%B0%20%EC%9E%A0%EA%B8%88%20%E2%86%92%20Circle%20%EC%A0%95%EB%A6%AC%20%E2%86%92%20%EC%BD%98%ED%85%90%EC%B8%A0%20%EC%82%AD%EC%A0%9C%20%E2%86%92%20%EC%9D%B5%EB%AA%85%ED%99%94%20%E2%86%92%20%EA%B8%B0%EB%A1%9D%0A%20%20F-%3E%3EA%3A%20Auth%20%EC%82%AC%EC%9A%A9%EC%9E%90%20%EC%82%AD%EC%A0%9C%20(%EB%A7%88%EC%A7%80%EB%A7%89)%0A%20%20F--%3E%3EC%3A%20%7Bok%3A%20true%7D%0A%20%20C-%3E%3EC%3A%20%EB%A1%9C%EA%B7%B8%EC%95%84%EC%9B%83%2C%20%EC%9D%B4%20%EA%B8%B0%EA%B8%B0%EC%9D%98%20%EC%BA%90%EC%8B%9C%20%EC%A7%80%EC%9A%B0%EA%B8%B0%0A%20%20C--%3E%3EU%3A%20%2Flogin%20%22%EA%B3%84%EC%A0%95%EC%9D%84%20%EC%82%AD%EC%A0%9C%ED%96%88%EC%96%B4%EC%9A%94%22%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<ul><li><strong>최근 로그인 필요</strong>: 서버는 ID 토큰의 로그인 시각(<code>auth_time</code>)이 10분 이내가 아니면 &quot;보안을 위해 다시 로그인한 뒤 삭제해주세요&quot;로 거절합니다. 클라이언트는 그래서 항상 재인증부터 합니다.</li><li><strong>Apple 연결 해제</strong>: Apple 사용자는 재인증에서 받은 토큰으로 Apple 쪽 연결을 끊습니다(5.1.1(v)). 오프라인이면 멈추고 다시 시도하게 하고, 그 밖의 이유로 실패하면 삭제는 그대로 진행한 뒤 로그인 화면에서 iPhone 설정에서 직접 지우는 방법을 안내합니다. 성공 여부는 삭제 기록(<code>appleRevoked</code>)에 남습니다.</li><li><strong>오래 걸려도 끝까지</strong>: 큰 계정은 오래 걸릴 수 있어 클라이언트는 540초까지 기다립니다. 호출이 실패하거나 시간이 지나도 Auth 사용자가 이미 지워졌다면 성공으로 처리합니다.</li><li><strong>다시 시도 가능</strong>: 모든 단계가 멱등적이고 Auth 사용자를 마지막에 지우므로, 중간에 실패하면 아직 로그인된 사용자가 그대로 다시 시도하면 됩니다.</li></ul><h3 id="deletion-scope" tabindex="-1">무엇을 지우고 무엇을 남기나요 <a class="header-anchor" href="#deletion-scope" aria-label="Permalink to &quot;무엇을 지우고 무엇을 남기나요 {#deletion-scope}&quot;">​</a></h3><p>원칙은 <strong>&quot;내 것은 지우고, 다른 사람에게 이미 의미가 생긴 것은 나와의 연결만 끊는다&quot;</strong> 입니다. → <a href="/grato-docs/decisions#adr-15">결정 기록 #15</a></p><table tabindex="0"><thead><tr><th>처리</th><th>대상</th></tr></thead><tbody><tr><td><strong>삭제</strong></td><td>계정(Auth), <code>users</code>(차단 목록 포함), 공개 프로필, 이름 선점, 내 감사 글과 거기 달린 댓글(누가 썼든), 다른 글에 남긴 내 댓글, 리액션 속 내 uid, 통계·배지, 공유 opt-in(<code>publicShares</code>), 푸시 토큰, 보낸 의견, 검토 중·반려된 질문 제안, 모든 제안의 원문(<code>questionOriginals</code>), 질문 하루 한도, 통계 마커, 프로필 사진(Storage)</td></tr><tr><td><strong>Circle</strong></td><td>참여한 Circle에서 모두 나감. 내가 관리자이고 다른 멤버가 있으면 <strong>가장 오래 함께한 멤버</strong>가 관리자가 됨. 혼자 있는 Circle은 삭제(초대 코드·사진 포함). 내보낸 멤버 목록과 초대 코드 발급자에서도 빠짐</td></tr><tr><td><strong>익명화해서 남김</strong></td><td>선정된(또는 선정 후 숨긴) 제안 질문: 작성자 정보만 지움. 이용 통계 이벤트: uid만 지움. 내가 보낸 신고: 신고자만 지움. 나에 대한 신고: 대상 계정·발췌를 지움(1년 뒤 TTL 삭제). 운영자 조치 기록: 대상 uid를 지움</td></tr><tr><td><strong>기간이 지나면 지워짐</strong></td><td>알림 발송 기록(30일), 서버 로그(30일), 토큰 잠금 표시(약 2시간), 장애 복구용 백업</td></tr><tr><td><strong>남는 것</strong></td><td>다른 사람의 차단 목록에 남은 uid (그 사람만 보고, 연결된 정보 없음)</td></tr></tbody></table><p>삭제가 끝나면 <code>adminAuditLogs</code>에 <code>account_deleted</code>를 <strong>개수만</strong> 남깁니다(uid 없음).</p><h3 id="늦게-도착한-작업이-데이터를-되살리지-않도록" tabindex="-1">늦게 도착한 작업이 데이터를 되살리지 않도록 <a class="header-anchor" href="#늦게-도착한-작업이-데이터를-되살리지-않도록" aria-label="Permalink to &quot;늦게 도착한 작업이 데이터를 되살리지 않도록&quot;">​</a></h3><p>삭제 중이거나 직후에도 이미 발급된 ID 토큰은 최대 1시간 유효하고, 트리거는 늦게 실행될 수 있습니다.</p><ul><li>삭제를 시작하자마자 서버 전용 <code>disabledUsers/{uid}</code>(약 2시간, TTL)를 씁니다. 규칙과 callable은 이 기간 동안 그 계정의 새 쓰기를 거부합니다.</li><li>통계·배지 트리거는 사용자 문서나 글이 없으면 아무것도 다시 만들지 않습니다. 차단·이름 신고 트리거도 삭제 중인 계정에는 신고를 만들지 않습니다.</li></ul><p>이용 정지(<code>moderate</code>의 <code>disableUser</code>)도 같은 잠금을 씁니다. → <a href="/grato-docs/architecture/security-rules#active-user">보안 규칙</a></p><h2 id="legal-pages" tabindex="-1">고객지원과 약관 페이지 <a class="header-anchor" href="#legal-pages" aria-label="Permalink to &quot;고객지원과 약관 페이지 {#legal-pages}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>경로</th><th>내용</th></tr></thead><tbody><tr><td><code>/terms</code></td><td>이용약관 (금지 콘텐츠와 무관용 원칙, 신고 24시간 처리, 이용 제한과 이의 신청)</td></tr><tr><td><code>/privacy</code></td><td>개인정보 처리방침 (처리 목적·항목·보유 기간, 위탁, 국외 이전, 자동 수집 장치, 보호책임자 등)</td></tr><tr><td><code>/support</code></td><td>고객지원: 문의, 신고·차단 방법, 계정 삭제, 운영자 정보</td></tr><tr><td><code>/account-deletion</code></td><td>계정 삭제 안내 (위)</td></tr></tbody></table><ul><li>본문은 <code>src/content/legalPages.js</code>, 공통 값(약관·처리방침 버전, 운영자 정보, 시행일, 고객지원 이메일)은 <code>src/content/legal.js</code> 한 곳에 있습니다. 네 페이지 모두 같은 <code>LegalDocument</code> 컴포넌트로 그리고, 빌드 때 정적 HTML로 미리 렌더링합니다.</li><li>값(예: 시행일 <code>EFFECTIVE_DATE</code>)이 아직 중괄호 자리 표시로 남아 있으면 페이지에 강조되어 보이고, <strong>Hosting 배포가 거부됩니다</strong>(<code>scripts/checkLegalPlaceholders.js</code>). → <a href="/grato-docs/operations/deploy#release-phase2">배포</a></li><li>로그인·온보딩·소개 페이지 아래에 약관·처리방침·고객지원 링크(<code>LegalLinks</code>)가 있고, MyPage › 설정에 &quot;고객 지원&quot;이 있습니다.</li><li><code>src/content/legal.test.js</code>가 처리방침의 법정 항목, 약관의 무관용·24시간·연령 조항, 삭제 안내의 두 경로와 보관 기간이 빠지지 않았는지 확인합니다.</li></ul><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li>데이터: <a href="/grato-docs/architecture/data-model#users"><code>users.consent</code></a>, <a href="/grato-docs/architecture/data-model#disabled-users"><code>disabledUsers</code></a></li><li>함수: <a href="/grato-docs/architecture/cloud-functions#delete-account">deleteAccount</a></li><li>감사 글 하나만 지우기: <a href="/grato-docs/features/gratitudes#delete">감사 글: 수정과 삭제</a></li></ul>',14))])}const k=r(u,[["render",p]]);export{B as __pageData,k as default};
